CREATE OR REPLACE PACKAGE rpt_estado_cuenta AUTHID CURRENT_USER AS
    FUNCTION build(
        p_cod_alumno IN VARCHAR2,
        p_app_user IN VARCHAR2 DEFAULT USER
    ) RETURN BLOB;
END rpt_estado_cuenta;
/

CREATE OR REPLACE PACKAGE BODY rpt_estado_cuenta AS

    -- Consulta ALUMNO (q_alumno.sql)
    FUNCTION q_alumno RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_ALUMNO: grupo maestro (una fila). Las columnas de fórmula (importe neto,
-- cuota mensual, deuda total) van como expresiones del SELECT.
select a.cod_alumno,
       a.carrera,
       a.nombre,
       a.fec_matricula,
       a.modalidad,
       a.sede,
       a.costo_programa,
       a.saldo_anterior,
       a.seguro,
       a.beca,
       nvl(a.costo_programa, 0) + nvl(a.saldo_anterior, 0)
         + nvl(a.seguro, 0) - nvl(a.beca, 0)            as importe_neto,
       a.cuota_pension,
       a.cuota_servicios,
       a.cuota_pension + a.cuota_servicios              as cuota_mensual,
       a.nro_cuotas,
       a.servicios_total,
       a.costo_programa + a.servicios_total             as deuda_total,
       a.recargo_mensual
  from pruebap_alumno a
 where a.cod_alumno = :P_COD_ALUMNO~');
    END q_alumno;

    -- Consulta ATRASOS (q_atrasos.sql)
    FUNCTION q_atrasos RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_ATRASOS: meses con pago atrasado.
select a.anio,
       lpad(a.mes, 2, '0')  as mes,
       a.nro,
       a.importe
  from pruebap_alumno_atraso a
 where a.cod_alumno = :P_COD_ALUMNO
 order by a.nro~');
    END q_atrasos;

    -- Consulta CAJA (q_caja.sql)
    FUNCTION q_caja RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_CAJA: cuotas pagadas en caja.
select c.anio,
       lpad(c.mes, 2, '0')                        as mes,
       c.caja,
       c.nro_cuota,
       c.pension,
       c.servicios,
       c.descuento,
       c.mora,
       c.pension + c.servicios + nvl(c.mora, 0)   as total,
       c.boleta,
       c.pension + c.servicios                    as importe
  from pruebap_alumno_cuota c
 where c.cod_alumno = :P_COD_ALUMNO
   and c.estado = 'C'
 order by c.nro_cuota~');
    END q_caja;

    -- Consulta CUOTAS (q_cuotas.sql)
    FUNCTION q_cuotas RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_CUOTAS: cuotas por pagar.
select c.anio,
       lpad(c.mes, 2, '0')        as mes,
       c.caja,
       c.nro_cuota,
       c.pension,
       c.servicios,
       c.pension + c.servicios    as total
  from pruebap_alumno_cuota c
 where c.cod_alumno = :P_COD_ALUMNO
   and c.estado = 'P'
 order by c.nro_cuota~');
    END q_cuotas;

    -- Consulta RESUMEN (q_resumen.sql)
    FUNCTION q_resumen RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_RESUMEN: columnas de resumen calculadas en SQL.
select r.*,
       r.costo_total - r.pagos_caja - r.becas
         - r.pagos_transferencia - nvl(r.otros_abonos, 0) + r.devoluciones   as saldo
  from (select a.costo_programa + a.servicios_total                    as costo_total,
               (select nvl(sum(c.pension + c.servicios), 0)
                  from pruebap_alumno_cuota c
                 where c.cod_alumno = a.cod_alumno
                   and c.estado = 'C')                                 as pagos_caja,
               nvl(a.beca, 0)                                          as becas,
               (select nvl(sum(t.pension + t.servicios + nvl(t.mora, 0)), 0)
                  from pruebap_alumno_transferencia t
                 where t.cod_alumno = a.cod_alumno)                    as pagos_transferencia,
               cast(null as number)                                    as otros_abonos,
               0                                                       as devoluciones
          from pruebap_alumno a
         where a.cod_alumno = :P_COD_ALUMNO) r~');
    END q_resumen;

    -- Consulta TRANSFERENCIAS (q_transferencias.sql)
    FUNCTION q_transferencias RETURN CLOB IS
    BEGIN
        RETURN to_clob(q'~-- Q_TRANSFERENCIAS: pagos por transferencia bancaria.
select t.nro,
       t.fecha,
       t.nro_operacion,
       t.nro_cuota,
       t.pension,
       t.servicios,
       t.descuento,
       t.mora,
       t.pension + t.servicios + nvl(t.mora, 0)  as total
  from pruebap_alumno_transferencia t
 where t.cod_alumno = :P_COD_ALUMNO
 order by t.nro~');
    END q_transferencias;

