    FUNCTION build(
        p_cod_alumno IN VARCHAR2,
        p_app_user IN VARCHAR2 DEFAULT USER
    ) RETURN BLOB IS
        l_queries JSON_OBJECT_T := JSON_OBJECT_T();
        l_values  JSON_OBJECT_T := JSON_OBJECT_T();
        l_query   JSON_OBJECT_T;
        l_binds   JSON_ARRAY_T;
    BEGIN
        IF p_cod_alumno IS NULL THEN
            RAISE_APPLICATION_ERROR(-20740, 'Falta el parámetro obligatorio P_COD_ALUMNO.');
        END IF;
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_alumno);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('ALUMNO', l_query);
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_atrasos);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('ATRASOS', l_query);
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_caja);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('CAJA', l_query);
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_cuotas);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('CUOTAS', l_query);
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_resumen);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('RESUMEN', l_query);
        l_query := JSON_OBJECT_T();
        l_query.put('sql', q_transferencias);
        l_binds := JSON_ARRAY_T();
        l_binds.append('P_COD_ALUMNO');
        l_query.put('binds', l_binds);
        l_queries.put('TRANSFERENCIAS', l_query);
        l_values.put('REPORT_TITLE', q'~ESTADO DE CUENTA DEL ALUMNO~');
        l_values.put('APP_USER', p_app_user);
        l_values.put('CODIGO', q'~EDU-CTA-01~');
        l_values.put('MODULO', q'~Tesorería~');
        l_values.put('SISTEMA', q'~ACADEMIA DEMO~');
        RETURN rpt_layout.render(
            p_layout  => layout,
            p_queries => l_queries.to_clob,
            p_values  => l_values.to_clob,
            p_binds   => rpt_layout.t_binds(
                rpt_layout.bind_text('P_COD_ALUMNO', p_cod_alumno)
            )
        );
    END build;

END rpt_estado_cuenta;
